#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_inorder_display_non_empty_tree(void) {
    // Setup: Build a non-empty binary tree to trigger the path (curr != NULL)
    int values[] = {5, 3, 7, 2, 4, 6, 8};
    int size = sizeof(values) / sizeof(values[0]);
    node* root = NULL;
    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    // Capture stdout to verify the function prints something
    stdout_capture_t* cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    // Test: call inorder_display on non-empty tree
    inorder_display(root);

    // Stop capture and get output
    char* output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Assertions: output should not be empty (since tree is non-empty)
    TEST_ASSERT_NOT_EQUAL_STRING("", output);

    // Cleanup
    free(output);
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_inorder_display_non_empty_tree);
    return UNITY_END();
}

